import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, add, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as dummyPrimitive } from '@/primitives';
import { createText as dummyText } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container group
  const container = new Group();

  // Determine aspect ratio from atlas region (512 / 320 = 1.6)
  const geometry = new PlaneGeometry(1.6, 1);

  // Basic node material (transparent to allow alpha)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const plane = new Mesh(geometry, material);
  container.add(plane);

  // Track loaded texture for cleanup
  let loadedTexture = null;

  // Load image texture and apply atlas UV transform
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;

      const region = {
        x: 0,
        y: 0,
        width: 512,
        height: 320,
      };

      const fullW = tex.image?.width || region.width;
      const fullH = tex.image?.height || region.height;

      const repeatX = region.width / fullW;
      const repeatY = region.height / fullH;
      const offsetX = region.x / fullW;
      const offsetY = region.y / fullH;

      const uvNode = uv();
      const transformedUV = add(mul(uvNode, vec2(repeatX, repeatY)), vec2(offsetX, offsetY));

      material.map = texture(tex, transformedUV);
      material.needsUpdate = true;
    });
  }

  // Store primitive instances for cleanup
  const primitiveInstances = [];

  // Apply any cinematic primitives defined in config (none expected now)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (fn) {
        const instance = fn(container, primitive.params);
        primitiveInstances.push(instance);
      }
    });
  }

  // Billboard behaviour: always face the camera
  plane.onBeforeRender = (renderer, scene, camera) => {
    plane.quaternion.copy(camera.quaternion);
  };

  // UserData with empty handlers and cleanup
  container.userData = {
    handlers: {},
    cleanup: () => {
      // Dispose geometry and material
      geometry.dispose();
      material.dispose();

      // Dispose loaded texture if any
      if (loadedTexture && typeof loadedTexture.dispose === 'function') {
        loadedTexture.dispose();
      }

      // Cleanup primitives
      primitiveInstances.forEach((inst) => {
        if (inst && typeof inst.cleanup === 'function') {
          inst.cleanup();
        }
      });

      // Kill any GSAP tweens attached to this container
      gsap.killTweensOf(container);
    },
  };

  return container;
}
